const ico=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.file}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SEED={taxRates:[0,5,12,18,28],cessRates:[0,1,5,12],business:{legalName:'',tradeName:'',gstin:'',address:'',state:'Uttar Pradesh',stateCode:'09',pan:'',phone:'',email:'',website:'',bank:'',account:'',ifsc:'',upi:'',terms:'Payment due within 15 days. Please quote the invoice number with your payment.',signatory:''},customers:[],products:[],invoices:[],payments:[],template:'modern',theme:'light',plan:'Free',businessEmail:'',invoicePrefix:'INV',invoiceCount:0};
let data; try{data={...SEED,...JSON.parse(localStorage.getItem('invoiceflow_data_v1')||'{}')};}catch{data={...SEED}}
if(!data.business)data.business=SEED.business;if(!data.taxRates)data.taxRates=SEED.taxRates;if(!data.cessRates)data.cessRates=SEED.cessRates;if(!data.customers)data.customers=SEED.customers;if(!data.products)data.products=SEED.products;if(!data.invoices)data.invoices=SEED.invoices;if(!data.payments)data.payments=[];
let state={page:'Overview',editor:false,filter:'All',search:'',draft:null,modal:null,template:data.template||'modern',customerSearch:''};
const persist=()=>{try{localStorage.setItem('invoiceflow_data_v1',JSON.stringify(data));if(state.draft)localStorage.setItem('invoiceflow_draft_v1',JSON.stringify(state.draft));else localStorage.removeItem('invoiceflow_draft_v1')}catch{}};try{state.draft=JSON.parse(localStorage.getItem('invoiceflow_draft_v1')||'null')}catch{state.draft=null}
if(data.theme==='dark')document.body.classList.add('dark');
