const navItems=[['Overview','grid'],['Invoices','invoice'],['Payments','payment'],['Customers','users'],['Products','box'],['Reports','chart'],['Templates','template'],['Water Plant','droplet'],['Settings','settings']];
function sidebar(){return `<aside class="sidebar"><div class="brand"><div class="brand-mark"><svg width="21" height="21" viewBox="0 0 24 24" fill="currentColor"><path d="M12 21S3 15.6 3 8.8C3 5 7.4 3.2 12 7.4 16.6 3.2 21 5 21 8.8 21 15.6 12 21 12 21Z"/></svg></div><div class="brand-name">i<span>♥</span>invoice.net</div></div><button class="workspace-switch" data-action="workspace"><span class="workspace-avatar">${esc((data.business.tradeName||data.business.legalName||'B').charAt(0).toUpperCase())}</span><span class="workspace-text"><strong>${esc(data.business.tradeName||data.business.legalName||'Add business name')}</strong><small>${data.business.gstin?'GST business':'Setup in progress'} · ${esc(data.business.stateCode||'09')}</small></span>${ico('down',15)}</button><div class="nav-label">WORKSPACE</div><nav><div class="nav-list">${navItems.map(([label,icon])=>`<button class="nav-item ${state.page===label&&!state.editor?'active':''}" data-page="${label}"><span class="nav-icon">${ico(icon,18)}</span><span>${label}</span></button>`).join('')}</div></nav><div class="sidebar-spacer"></div><div class="plan-card"><div class="plan-top"><b>${data.plan==='Free'?'Free plan':'iluvinvoice.net Pro'}</b><span class="plan-pill">${data.plan==='Free'?'FREE':'PRO'}</span></div><div class="plan-copy">${data.plan==='Free'?`${Math.max(0,10-data.invoiceCount)} of 10 invoices left this month`:'Unlimited invoices'}</div><div class="plan-meter"><i style="width:${data.plan==='Free'?Math.min(100,data.invoiceCount*10):100}%"></i></div><button class="plan-upgrade" data-action="upgrade">Explore Pro ${ico('arrow',12)}</button></div><div class="user-row"><div class="user-avatar">Y</div><div class="user-meta"><b>Your account</b><small>${esc(data.businessEmail||'Complete your profile')}</small></div><button class="icon-button" data-action="account">${ico('more',17)}</button></div></aside>`}
function topbar(){return `<header class="topbar"><div class="crumbs"><span>Workspace</span>${ico('chevron',12)}<strong>${state.editor?'New invoice':esc(state.page)}</strong></div><div class="topbar-spacer"></div><label class="search-box">${ico('search',15)}<input id="globalSearch" placeholder="Search anything…" value="${esc(state.search)}"><kbd>⌘ K</kbd></label><button class="top-action" data-action="theme" title="Toggle appearance">${ico(data.theme==='dark'?'sun':'moon',16)}</button><button class="top-action" data-action="notifications" title="Notifications">${ico('bell',16)}</button><button class="button button-primary" data-action="new">${ico('plus',15)} New invoice</button></header>`}
function head(title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${state.page==='Overview'?new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).toUpperCase():'YOUR WORKSPACE'}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${action}</div></div>`}
function metric(title,value,foot,icon,trend=''){return `<div class="metric-card"><div class="metric-head"><span>${title}</span><span class="metric-icon">${ico(icon,15)}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${trend?`<span class="trend-up">${trend}</span>`:''}<span class="muted">${foot}</span></div></div>`}
function chart(){let now=new Date(),months=[];for(let i=5;i>=0;i--){let d=new Date(now.getFullYear(),now.getMonth()-i,1),key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,total=data.invoices.filter(x=>(x.date||'').slice(0,7)===key).reduce((a,x)=>a+toPaise(x.amount),0n);months.push({label:d.toLocaleDateString('en-IN',{month:'short'}).toUpperCase(),total})}let max=months.reduce((a,x)=>x.total>a?x.total:a,0n),vals=months.map(x=>max?Math.max(5,Number(x.total*100n/max)):0),xs=vals.map((_,i)=>50+i*115),ys=vals.map(v=>162-v*1.32),points=()=>xs.map((x,i)=>`${x},${ys[i]}`).join(' '),area=`${xs[0]},162 ${points()} ${xs.at(-1)},162`;return `<svg class="chart-svg" viewBox="0 0 670 190" preserveAspectRatio="none"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#67a980" stop-opacity=".2"/><stop offset="1" stop-color="#67a980" stop-opacity="0"/></linearGradient></defs>${[35,75,115,155].map(y=>`<line x1="35" y1="${y}" x2="645" y2="${y}" class="chart-gridline"/>`).join('')}<polygon points="${area}" fill="url(#chartFill)"/><polyline points="${points()}" fill="none" stroke="#4f9a6d" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/>${vals.map((v,i)=>`<circle cx="${xs[i]}" cy="${ys[i]}" r="3" fill="#fff" stroke="#4f9a6d" stroke-width="2"/>`).join('')}${months.map((m,i)=>`<text x="${xs[i]-10}" y="187" class="chart-label">${m.label}</text>`).join('')}</svg>`}
function invoiceRows(items=data.invoices.slice(0,5)){return items.map(i=>`<tr><td><span class="invoice-id">${esc(i.id)}</span></td><td><div class="party-name">${esc(i.customer)}</div><div class="party-sub">${esc(i.gstin||'B2C customer')}</div></td><td>${dateFmt(i.date)}</td><td><span class="status ${statusClass(i.status)}">${esc(i.status)}</span></td><td class="amount-cell">${inr(toPaise(i.amount))}</td><td><div class="row-actions"><button class="icon-button" data-action="view-invoice" data-id="${esc(i.id)}" title="Preview">${ico('file',15)}</button><button class="icon-button" data-action="invoice-menu" data-id="${esc(i.id)}">${ico('more',15)}</button></div></td></tr>`).join('')}
function dateFmt(d){if(!d)return '—';let x=new Date(d+'T00:00:00');return x.toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}
function invoiceTable(items){return `<div class="panel table-panel"><div class="panel-header"><div><h3>Recent invoices</h3><p>Keep an eye on the latest activity</p></div><button class="text-link" data-page="Invoices">All invoices ${ico('arrow',12)}</button></div><div class="table-wrap"><table class="invoice-table"><thead><tr><th>Invoice</th><th>Customer</th><th>Issue date</th><th>Status</th><th>Amount</th><th></th></tr></thead><tbody>${invoiceRows(items)||'<tr><td colspan="6" class="empty-state">No invoices yet</td></tr>'}</tbody></table></div></div>`}
function overview(){let m=data.invoices.reduce((a,i)=>{let amount=toPaise(i.amount),paid=i.status==='Paid'?amount:toPaise(i.paid||'0');a.sales+=amount;a.paid+=paid;a.outstanding+=amount>paid?amount-paid:0n;if(i.status==='Overdue')a.overdue++;else if(i.status==='Unpaid')a.unpaid++;return a},{sales:0n,paid:0n,outstanding:0n,overdue:0,unpaid:0});let tax=data.invoices.filter(i=>i.status==='Paid').reduce((a,i)=>{(i.items||[]).forEach(it=>{let line=lineMath(it);a+=line.tax+line.cess});return a},0n);let totalCount=data.invoices.length,paidCount=data.invoices.filter(i=>i.status==='Paid').length,overdueCount=data.invoices.filter(i=>i.status==='Overdue').length,awaitCount=totalCount-paidCount-overdueCount,paidPct=totalCount?paidCount/totalCount*100:0,awaitPct=totalCount?awaitCount/totalCount*100:0;return `${head('Welcome to iluvinvoice.net','Set up your workspace and create your first professional invoice.',`<select class="period-select"><option>This month</option><option>Last month</option><option>This quarter</option></select><button class="button button-primary" data-action="new">${ico('plus',14)} Create invoice</button>`)}<section class="welcome-banner"><div class="banner-copy"><div class="eyebrow">YOUR BUSINESS, IN GOOD ORDER</div><h2>Make room for the work<br>you love.</h2><p>Add your business details, first customer and services to get started.</p><button class="button" data-action="new">Create an invoice ${ico('arrow',13)}</button></div><div class="banner-art"><svg viewBox="0 0 220 135" fill="none"><rect x="38" y="14" width="131" height="102" rx="10" fill="#F8FBF7"/><rect x="51" y="28" width="41" height="7" rx="3.5" fill="#D6E8DA"/><rect x="51" y="45" width="102" height="2" rx="1" fill="#E7EEE8"/><rect x="51" y="56" width="102" height="2" rx="1" fill="#E7EEE8"/><rect x="51" y="67" width="72" height="2" rx="1" fill="#E7EEE8"/><rect x="51" y="83" width="102" height="18" rx="4" fill="#EAF3EB"/><path d="m119 35 10 8 18-20" stroke="#4F936B" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><circle cx="175" cy="94" r="27" fill="#D7F0B4"/><path d="M169 95h12m-6-6v12" stroke="#356449" stroke-width="3" stroke-linecap="round"/><circle cx="43" cy="111" r="11" fill="#F1BC71"/><path d="M40 111h6m-3-3v6" stroke="#fff" stroke-width="1.5" stroke-linecap="round"/></svg></div></section><section class="metric-grid">${metric('Total sales',inr(m.sales),'Across all invoices','chart')}${metric('Tax collected',inr(tax),'On paid invoices','file')}${metric('Outstanding',inr(m.outstanding),'Balance still due','invoice')}${metric('Paid amount',inr(m.paid),'Across paid invoices','check')}</section><section class="metric-grid secondary-metrics">${metric('Unpaid invoices',m.unpaid,'Awaiting payment','invoice')}${metric('Overdue invoices',m.overdue,'Past due date','invoice')}${metric('Customers',data.customers.length,'In your customer book','users')}</section><section class="dashboard-grid"><div class="panel"><div class="panel-header"><div><h3>Revenue overview</h3><p>Sales performance over the last 6 months</p></div><div class="chart-legend"><span class="legend"><i></i>Invoice sales</span></div></div><div class="chart-area">${chart()}</div></div><div class="panel"><div class="panel-header"><div><h3>Invoice health</h3><p>A snapshot of your receivables</p></div><button class="icon-button">${ico('more',16)}</button></div><div class="donut-wrap"><div class="donut" style="background:conic-gradient(#2d7457 0 ${paidPct}%,#d5e9dd ${paidPct}% ${paidPct+awaitPct}%,#f0c67d ${paidPct+awaitPct}% 100%)"><div class="donut-center"><b>${data.invoices.length}</b><span>invoices</span></div></div><div class="donut-key"><div><i class="green-dot"></i><span>Paid</span><b>${data.invoices.filter(i=>i.status==='Paid').length}</b></div><div><i class="mint-dot"></i><span>Awaiting</span><b>${awaitCount}</b></div><div><i class="gold-dot"></i><span>Overdue</span><b>${data.invoices.filter(i=>i.status==='Overdue').length}</b></div></div></div></div></section>${invoiceTable(data.invoices.slice(0,5))}`}
function invoicesPage(){let q=state.search.toLowerCase();let rows=data.invoices.filter(i=>(state.filter==='All'||i.status===state.filter)&&(!q||`${i.id} ${i.customer} ${i.gstin}`.toLowerCase().includes(q)));return `${head('Invoices','A clear view of every bill, from draft to paid.',`<button class="button button-primary" data-action="new">${ico('plus',14)} New invoice</button>`)}<div class="toolbar-row"><div class="filter-tabs">${['All','Paid','Unpaid','Overdue','Draft'].map(x=>`<button class="filter-tab ${state.filter===x?'active':''}" data-filter="${x}">${x}${x==='All'?` · ${data.invoices.length}`:''}</button>`).join('')}</div><div class="table-actions"><label class="list-search">${ico('search',14)}<input id="pageSearch" placeholder="Search invoices" value="${esc(state.search)}"></label><button class="button button-secondary" data-action="export">Export</button></div></div><div class="panel table-panel"><div class="table-wrap"><table class="invoice-table"><thead><tr><th>Invoice number</th><th>Customer</th><th>Issue date</th><th>Due date</th><th>Status</th><th>Amount</th><th></th></tr></thead><tbody>${rows.map(i=>`<tr><td><span class="invoice-id">${esc(i.id)}</span></td><td><div class="party-name">${esc(i.customer)}</div><div class="party-sub">${esc(i.gstin||'B2C customer')}</div></td><td>${dateFmt(i.date)}</td><td>${dateFmt(i.due)}</td><td><span class="status ${statusClass(i.status)}">${esc(i.status)}</span></td><td class="amount-cell">${inr(toPaise(i.amount))}</td><td><div class="row-actions"><button class="icon-button" data-action="view-invoice" data-id="${esc(i.id)}">${ico('file',15)}</button><button class="icon-button" data-action="invoice-menu" data-id="${esc(i.id)}">${ico('more',15)}</button></div></td></tr>`).join('')||`<tr><td colspan="7"><div class="empty-state"><h3>No invoices found</h3><p>Try a different search or create an invoice.</p></div></td></tr>`}</tbody></table></div></div>`}
function paymentsPage(){let total=data.payments.reduce((a,p)=>a+toPaise(p.amount),0n),rows=[...data.payments].sort((a,b)=>String(b.date).localeCompare(String(a.date)));return `${head('Payments','Record receipts and keep outstanding balances up to date.',`<button class="button button-primary" data-action="record-payment">${ico('plus',14)} Record payment</button>`)}<section class="metric-grid">${metric('Payments recorded',rows.length,'Receipt entries','payment')}${metric('Total received',inr(total),'Recorded in this workspace','check')}${metric('Invoices to follow up',data.invoices.filter(i=>!['Paid','Draft'].includes(i.status)).length,'Part-paid, unpaid or overdue','invoice')}</section><div class="panel table-panel"><div class="panel-header"><div><h3>Payment activity</h3><p>Receipts recorded against your invoices</p></div><span class="mini-tag">Local preview records</span></div><div class="table-wrap"><table class="invoice-table"><thead><tr><th>Receipt</th><th>Invoice / customer</th><th>Date</th><th>Method</th><th>Reference</th><th>Amount</th></tr></thead><tbody>${rows.map(p=>`<tr><td><span class="invoice-id">${esc(p.id)}</span></td><td><div class="party-name">${esc(p.invoiceId)}</div><div class="party-sub">${esc(p.customer||'')}</div></td><td>${dateFmt(p.date)}</td><td>${esc(p.method||'—')}</td><td>${esc(p.reference||'—')}</td><td class="amount-cell">${inr(toPaise(p.amount))}</td></tr>`).join('')||`<tr><td colspan="6"><div class="empty-state"><h3>No payments recorded yet</h3><p>Open an unpaid invoice and record a full or partial payment.</p></div></td></tr>`}</tbody></table></div></div><div class="helper" style="margin-top:12px">Payment entries in this preview are local records only. They do not initiate or confirm a bank, UPI or card transaction.</div>`}
function customerCard(c,i){let colors=['','blue','pink'];return `<article class="entity-card"><div class="entity-top"><div class="entity-avatar ${colors[i%3]}">${esc(c.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div><strong>${esc(c.business||c.name)}</strong><small>${esc(c.name)}</small></div><button class="icon-button entity-menu" data-action="edit-customer" data-id="${esc(c.id)}">${ico('more',15)}</button></div><div class="entity-detail"><div>${ico('invoice',13)} ${esc(c.gstin||'Unregistered customer')}</div><div>${ico('mail',13)} ${esc(c.email||'No email')}</div><div>${ico('location',13)} ${esc(c.state||'')} · ${esc(c.stateCode||'')}</div></div><div class="entity-foot"><span>${data.invoices.filter(x=>x.customer===(c.business||c.name)).length} invoices</span><span>${esc(c.phone||'')}</span></div></article>`}
function customersPage(){let q=state.search.toLowerCase();let cs=data.customers.filter(c=>`${c.name} ${c.business} ${c.gstin}`.toLowerCase().includes(q));return `${head('Customers','Relationships worth keeping, all in one place.',`<button class="button button-primary" data-action="add-customer">${ico('plus',14)} Add customer</button>`)}<div class="toolbar-row"><div class="eyebrow" style="margin:0">${data.customers.length} CUSTOMERS</div><div class="table-actions"><label class="list-search">${ico('search',14)}<input id="pageSearch" placeholder="Search customers" value="${esc(state.search)}"></label></div></div><div class="customer-grid">${cs.map(customerCard).join('')||'<div class="empty-state">No customers yet.</div>'}</div>`}
function productCard(p,i){return `<article class="entity-card"><div class="entity-top"><div class="entity-avatar ${i%2?'blue':''}">${ico('box',17)}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.description||'Product / service')}</small></div><button class="icon-button entity-menu" data-action="edit-product" data-id="${esc(p.id)}">${ico('more',15)}</button></div><div class="product-price">${inr(toPaise(p.price))} <small>/ ${esc(p.unit||'unit')}</small></div><div class="product-meta"><span class="mini-tag">HSN ${esc(p.hsn||'—')}</span><span class="mini-tag">GST ${esc(p.gst)}%</span>${p.cess?`<span class="mini-tag">Cess ${esc(p.cess)}%</span>`:''}</div></article>`}
function productsPage(){let q=state.search.toLowerCase();return `${head('Products & services','Your repeat work, ready to add in a click.',`<button class="button button-primary" data-action="add-product">${ico('plus',14)} Add product</button>`)}<div class="toolbar-row"><div class="eyebrow" style="margin:0">${data.products.length} ITEMS</div><div class="table-actions"><label class="list-search">${ico('search',14)}<input id="pageSearch" placeholder="Search products" value="${esc(state.search)}"></label></div></div><div class="product-grid">${data.products.filter(p=>`${p.name} ${p.hsn}`.toLowerCase().includes(q)).map(productCard).join('')}</div>`}
function templatesPage(){let names=['Minimal','Modern Teal','Corporate Blue','Elegant Bronze','Classic GST','Ocean Premium','Burgundy Luxe','Graphite Pro'];let classes=['minimal','modern','corporate','elegant','classic','ocean','burgundy','graphite'];return `${head('Invoice templates','Choose a professional layout and apply it instantly to every new invoice.')}<div class="admin-banner">${ico('check',16)} Eight premium invoice styles are available. Select any design and preview it while creating an invoice.</div><div class="template-grid">${names.map((n,i)=>`<article class="template-card"><div class="template-thumb ${classes[i]}"><span class="mock-title">${i===4?'TAX INVOICE':BRAND.toUpperCase()}</span><div class="mock-lines"><i></i><i></i><i></i></div><div class="mock-total"></div></div><div class="template-meta"><div><strong>${n}</strong><small>${data.template===classes[i]?'Currently selected':'Ready to use'}</small></div><button class="button ${data.template===classes[i]?'button-soft':'button-secondary'}" data-action="select-template" data-template="${classes[i]}">${data.template===classes[i]?'Selected':'Use template'}</button></div></article>`).join('')}</div>`}
function reportsPage(){let sales=data.invoices.reduce((a,x)=>a+toPaise(x.amount),0n),paid=data.invoices.filter(x=>x.status==='Paid').reduce((a,x)=>a+toPaise(x.amount),0n),out=sales-paid;let tax=0n;data.invoices.forEach(x=>(x.items||[]).forEach(i=>tax+=lineMath(i).tax));return `${head('Business insights','A simple, useful pulse on your business.',`<select class="period-select"><option>Financial year 2026–27</option><option>Financial year 2025–26</option></select>`)}<div class="analytics-grid">${[['Gross sales',inr(sales)],['Payments received',inr(paid)],['Outstanding',inr(out)],['Tax on invoices',inr(tax)],['Active customers',data.customers.length],['Invoices created',data.invoices.length]].map(([a,b])=>`<div class="analytic-card"><span>${a}</span><strong>${b}</strong></div>`).join('')}</div><div style="height:15px"></div><div class="panel"><div class="panel-header"><div><h3>Revenue overview</h3><p>Issued invoice totals, before adjustments</p></div></div><div class="chart-area">${chart()}</div></div><div style="height:15px"></div>${invoiceTable(data.invoices.slice(0,5))}<p class="helper" style="margin-top:12px">Figures are based on invoices saved in iluvinvoice.net. They are not a substitute for statutory books or GST return filing.</p>`}
function settingsPage(){let b=data.business;return `${head('Business settings','Your business identity, thoughtfully organised.',`<button class="button button-secondary" data-action="account">Account & security</button>`)}<div class="settings-grid"><section class="settings-card"><h3>Business profile</h3><p>These details appear on your invoices.</p><form class="settings-form" id="businessForm"><div class="field-grid"><div class="field"><label>Legal name</label><input name="legalName" value="${esc(b.legalName)}" required></div><div class="field"><label>Trade name</label><input name="tradeName" value="${esc(b.tradeName)}"></div><div class="field"><label>GSTIN</label><input name="gstin" value="${esc(b.gstin)}" maxlength="15"></div><div class="field"><label>PAN (optional)</label><input name="pan" value="${esc(b.pan)}"></div><div class="field full"><label>Business address</label><input name="address" value="${esc(b.address)}"></div><div class="field"><label>State</label><select name="state">${stateOptions(b.state)}</select></div><div class="field"><label>State code</label><input name="stateCode" value="${esc(b.stateCode)}" maxlength="2"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(b.phone)}"></div><div class="field"><label>Email</label><input name="email" value="${esc(b.email)}"></div><div class="field"><label>Website</label><input name="website" value="${esc(b.website)}"></div><div class="field"><label>Business logo</label><input type="file" accept="image/png,image/jpeg,image/webp" data-upload="logo"><div class="helper">PNG, JPG or WebP · max 500 KB.</div></div><div class="field"><label>Signature</label><input type="file" accept="image/png,image/jpeg,image/webp" data-upload="signature"><div class="helper">Image signature · max 500 KB.</div></div></div><button class="button button-primary settings-save" type="submit">Save business profile</button></form></section><section class="settings-card"><h3>Payments & invoice defaults</h3><p>Make getting paid feel effortless.</p><form class="settings-form" id="paymentForm"><div class="field-grid"><div class="field"><label>Bank name</label><input name="bank" value="${esc(b.bank)}"></div><div class="field"><label>Account number</label><input name="account" value="${esc(b.account)}"></div><div class="field"><label>IFSC code</label><input name="ifsc" value="${esc(b.ifsc)}"></div><div class="field"><label>UPI ID</label><input name="upi" value="${esc(b.upi)}"></div><div class="field"><label>Invoice prefix</label><input name="invoicePrefix" value="${esc(data.invoicePrefix||'INV')}"></div><div class="field"><label>Signatory name</label><input name="signatory" value="${esc(b.signatory)}"></div><div class="field full"><label>Default terms & conditions</label><textarea name="terms">${esc(b.terms)}</textarea></div></div><button class="button button-primary settings-save" type="submit">Save payment details</button></form></section><section class="settings-card"><h3>Tax preferences</h3><p>Flexible defaults. Always review tax treatment before issuing.</p><div class="settings-form"><div class="field"><label>Place of supply behavior</label><select disabled><option>Determine from customer state</option></select><div class="helper">Tax components are calculated from your supplier state and place of supply. Confirm applicability with your tax adviser.</div></div><form id="taxForm" class="settings-form"><div class="field"><label>Configurable default GST rates (%)</label><input name="taxRates" value="${esc(data.taxRates.join(', '))}"><div class="helper">Comma-separated defaults. Maintain a current, reviewed tax configuration before production use.</div></div><div class="field"><label>Configurable cess presets (%)</label><input name="cessRates" value="${esc(data.cessRates.join(', '))}"></div><button class="button button-secondary" type="submit">Save tax presets</button></form><div class="admin-banner">GST rates, classifications, e-invoice rules and statutory requirements can change. iluvinvoice.net does not file returns or verify GST registrations.</div></div></section><section class="settings-card"><h3>Plan & usage</h3><p>Your iluvinvoice.net subscription at a glance.</p><div class="analytic-card" style="background:var(--surface-2);margin-bottom:12px"><span>Current plan</span><strong>${esc(data.plan)}${data.plan==='Pro'?' · Annual':''}</strong></div><div class="helper">Free plan includes up to 10 invoices per month and standard templates. Server-side feature enforcement and payment processing are not configured in this local preview.</div><button class="button button-secondary" style="margin-top:16px" data-action="upgrade">Explore plans ${ico('arrow',12)}</button></section></div>`}
function stateOptions(sel=''){let states=['Andaman and Nicobar Islands','Andhra Pradesh','Arunachal Pradesh','Assam','Bihar','Chandigarh','Chhattisgarh','Dadra and Nagar Haveli and Daman and Diu','Delhi','Goa','Gujarat','Haryana','Himachal Pradesh','Jammu and Kashmir','Jharkhand','Karnataka','Kerala','Ladakh','Lakshadweep','Madhya Pradesh','Maharashtra','Manipur','Meghalaya','Mizoram','Nagaland','Odisha','Puducherry','Punjab','Rajasthan','Sikkim','Tamil Nadu','Telangana','Tripura','Uttar Pradesh','Uttarakhand','West Bengal'];return states.map(s=>`<option ${s===sel?'selected':''}>${s}</option>`).join('')}
function render(){let app=document.getElementById('app');if(state.editor){app.innerHTML=`<div class="app-shell">${sidebar()}<main class="main">${topbar()}${editor()}</main></div><div class="toast-area" id="toastArea"></div>`}else{let content=state.page==='Overview'?overview():state.page==='Invoices'?invoicesPage():state.page==='Payments'?paymentsPage():state.page==='Customers'?customersPage():state.page==='Products'?productsPage():state.page==='Reports'?reportsPage():state.page==='Templates'?templatesPage():settingsPage();if(state.draft)content=`<div class="draft-resume"><div><strong>Invoice editor saved</strong><small>${esc(state.draft.id||'New invoice')} · saved on this device</small></div><button class="button button-soft" data-action="resume-draft">Resume editing ${ico('arrow',13)}</button><button class="icon-button" data-action="discard-draft" title="Discard draft">${ico('close',15)}</button></div>${content}`;app.innerHTML=`<div class="app-shell">${sidebar()}<main class="main">${topbar()}<div class="content">${content}</div></main></div><div class="toast-area" id="toastArea"></div>`}document.body.classList.toggle('dark',data.theme==='dark');if(state.editor)updatePreview();}
function newDraft(invoice){let d=invoice?JSON.parse(JSON.stringify(invoice)):{id:nextInvoiceNumber(),customer:'',gstin:'',address:'',state:data.business.state,stateCode:data.business.stateCode,reference:'',customLabel:'',customValue:'',date:new Date().toISOString().slice(0,10),due:new Date(Date.now()+14*86400000).toISOString().slice(0,10),type:'Tax Invoice',place:data.business.state,reverse:false,paid:'0',notes:'',items:[{name:'',description:'',hsn:'',qty:'1',unit:'Unit',rate:'0',discount:'0',gst:data.taxRates.includes(18)?18:data.taxRates[0],cess:0}]};d.saved=!!invoice;if(invoice)d.originalId=invoice.originalId||invoice.id;state.draft=d;state.editor=true;state.page='Invoices';persist();render()}
function nextInvoiceNumber(){let fy=new Date().getMonth()>=3?`${String(new Date().getFullYear()).slice(-2)}-${String(new Date().getFullYear()+1).slice(-2)}`:`${String(new Date().getFullYear()-1).slice(-2)}-${String(new Date().getFullYear()).slice(-2)}`;let seq=String(data.invoiceCount+1).padStart(3,'0');return `${data.invoicePrefix||'INV'}/${fy}/${seq}`}function financialYear(date){let d=new Date((date||new Date().toISOString().slice(0,10))+'T00:00:00'),y=d.getFullYear(),start=d.getMonth()>=3?y:y-1;return `${start}-${String(start+1).slice(-2)}`}
function editor(){let d=state.draft,c=calculate(d.items,d.place);let maxed=data.plan==='Free'&&data.invoiceCount>=10;return `<div class="editor-page"><div class="editor-top"><div class="editor-top-left"><button class="back-button" data-action="close-editor">${ico('arrow',16)}</button><div><h2>${d.saved?'Edit invoice':d.id||'New invoice'}</h2><p>Draft is saved automatically as you go</p></div></div><div class="editor-top-actions"><button class="button button-secondary" data-action="preview-download">${ico('download',14)} Print / Save PDF</button><button class="button button-primary" data-action="save-invoice" ${maxed?'disabled':''}>Save invoice ${ico('arrow',13)}</button></div></div><div class="editor-layout"><div class="editor-form"><section class="form-card business-identity-card"><div class="form-card-heading"><div><h3>Your business</h3><p class="section-copy">Shown as Billed By on this invoice</p></div><span class="step-no">LIVE BRANDING</span></div><div class="business-editor"><label class="logo-drop"><span class="logo-preview">${data.business.logoData?`<img src="${esc(data.business.logoData)}" alt="Business logo">`:ico('image',22)}</span><span><strong>${data.business.logoData?'Change logo':'Add business logo'}</strong><small>PNG, JPG or WebP · max 500 KB</small></span><input type="file" accept="image/png,image/jpeg,image/webp" data-upload="logo"></label><div class="field-grid"><div class="field"><label>Brand / company name</label><input data-business="tradeName" value="${esc(data.business.tradeName||'')}" placeholder="e.g. RR Water Plant"></div><div class="field"><label>Legal name</label><input data-business="legalName" value="${esc(data.business.legalName||'')}" placeholder="Registered name (optional)"></div><div class="field"><label>GSTIN</label><input data-business="gstin" value="${esc(data.business.gstin||'')}" maxlength="15"></div><div class="field"><label>PAN</label><input data-business="pan" value="${esc(data.business.pan||'')}"></div><div class="field full"><label>Business address</label><input data-business="address" value="${esc(data.business.address||'')}" placeholder="Street, city, PIN code"></div><div class="field"><label>Phone</label><input data-business="phone" value="${esc(data.business.phone||'')}"></div><div class="field"><label>Email</label><input data-business="email" value="${esc(data.business.email||'')}"></div></div></div></section><section class="form-card"><div class="form-card-heading"><h3>Invoice details</h3><span class="step-no">01 / DETAILS</span></div><div class="field-grid three"><div class="field"><label>Document type</label><select data-draft="type">${['Tax Invoice','Bill of Supply','Proforma Invoice','Quotation / Estimate','Credit Note','Debit Note','Delivery Challan'].map(x=>`<option ${d.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Invoice number</label><input data-draft="id" value="${esc(d.id)}"></div><div class="field"><label>Financial year</label><select data-fy disabled><option>${financialYear(d.date).replace('-','–')}</option></select></div><div class="field"><label>Invoice date</label><input type="date" data-draft="date" value="${esc(d.date)}"></div><div class="field"><label>Due date</label><input type="date" data-draft="due" value="${esc(d.due)}"></div><div class="field"><label>Supply type</label><select data-draft="supply"><option>B2B</option><option ${!d.gstin?'selected':''}>B2C</option></select></div><div class="field"><label>PO / reference number</label><input data-draft="reference" value="${esc(d.reference||'')}" placeholder="Optional"></div><div class="field"><label>Custom label</label><input data-draft="customLabel" value="${esc(d.customLabel||'')}" placeholder="e.g. Billing period"></div><div class="field"><label>Custom value</label><input data-draft="customValue" value="${esc(d.customValue||'')}" placeholder="e.g. Sep 2026"></div></div></section><section class="form-card"><div class="form-card-heading"><h3>Customer details</h3><button class="text-link" data-action="add-customer">+ Add new</button></div><div class="field-grid"><div class="field"><label>Customer / business name</label><input list="customerNames" data-draft="customer" value="${esc(d.customer)}" placeholder="Search or enter customer name"><datalist id="customerNames">${data.customers.map(x=>`<option value="${esc(x.business||x.name)}"></option>`).join('')}</datalist></div><div class="field"><label>Customer GSTIN / UIN</label><input data-draft="gstin" value="${esc(d.gstin)}" placeholder="15-character GSTIN (if registered)"></div><div class="field full"><label>Billing address</label><input data-draft="address" value="${esc(d.address)}" placeholder="Street, city, PIN code"></div><div class="field"><label>Customer state</label><select data-draft="state">${stateOptions(d.state)}</select></div><div class="field"><label>State code</label><input data-draft="stateCode" value="${esc(d.stateCode)}" maxlength="2" placeholder="e.g. 09"></div><div class="field"><label>Place of supply</label><select data-draft="place">${stateOptions(d.place||data.business.state)}</select></div><div class="field"><label>Shipping address</label><input data-draft="shipping" value="${esc(d.shipping||'')}" placeholder="Same as billing address"></div><div class="field full"><div class="switch-row"><span>Reverse charge applicable</span><button class="switch ${d.reverse?'on':''}" data-action="reverse-toggle" aria-label="Toggle reverse charge"><i></i></button></div></div></div></section><section class="form-card items-card"><div class="form-card-heading"><h3>Items & tax</h3><span class="step-no">${d.items.length} ${d.items.length===1?'ITEM':'ITEMS'}</span></div><div class="items-scroll"><table class="item-edit-table"><thead><tr><th style="width:24%">Product / service</th><th>HSN/SAC</th><th>Qty</th><th>Unit</th><th>Rate (₹)</th><th>Disc.</th><th>GST %</th><th>Cess %</th><th>Total</th><th></th></tr></thead><tbody>${d.items.map((it,i)=>{let m=lineMath(it);return `<tr data-item-row="${i}"><td><input class="item-name-input" data-item="name" data-i="${i}" value="${esc(it.name)}" placeholder="Item name"></td><td><input data-item="hsn" data-i="${i}" value="${esc(it.hsn)}" placeholder="HSN/SAC"></td><td><input data-item="qty" data-i="${i}" type="number" min="0" step="0.01" value="${esc(it.qty)}"></td><td><input data-item="unit" data-i="${i}" value="${esc(it.unit)}"></td><td><input data-item="rate" data-i="${i}" type="number" min="0" step="0.01" value="${esc(it.rate)}"></td><td><input data-item="discount" data-i="${i}" value="${esc(it.discount)}" title="Amount or percent" placeholder="0 or 5%"></td><td><select data-item="gst" data-i="${i}">${[...new Set([...data.taxRates,Number(it.gst)||0])].sort((a,b)=>a-b).map(n=>`<option ${Number(it.gst)===n?'selected':''}>${n}</option>`).join('')}</select></td><td><select data-item="cess" data-i="${i}">${[...new Set([...data.cessRates,Number(it.cess)||0])].sort((a,b)=>a-b).map(n=>`<option ${Number(it.cess)===n?'selected':''}>${n}</option>`).join('')}</select></td><td class="amount-cell">${inr(m.total)}</td><td><button class="remove-line" data-action="remove-item" data-i="${i}">${ico('close',13)}</button></td></tr>`}).join('')}</tbody></table></div><div class="add-item-row"><button class="add-item" data-action="add-item">${ico('plus',13)} Add another line</button><select id="quickProduct" class="period-select" style="height:29px;margin-left:9px;font-size:9px"><option value="">Add saved product…</option>${data.products.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></div></section><section class="form-card"><div class="form-card-heading"><h3>Payment & notes</h3><span class="step-no">OPTIONAL</span></div><div class="field-grid"><div class="field"><label>Amount already paid (₹)</label><input data-draft="paid" type="number" min="0" step="0.01" value="${esc(d.paid||'0')}"></div><div class="field"><label>Notes visible to customer</label><input data-draft="notes" value="${esc(d.notes||'')}" placeholder="A note of thanks, or payment reference"></div><div class="field full"><div class="helper">Tax split is based on supplier state and place of supply. Review the applicable tax treatment before issuing. Amounts are rounded to the nearest rupee on this preview.</div></div></div></section><section class="form-card summary-card"><div><div class="form-card-heading"><h3>Invoice summary</h3></div><div class="helper">${d.place===data.business.state?'Intra-state supply · CGST + SGST':'Inter-state supply · IGST'}${d.reverse?' · Reverse charge':''}</div></div><div class="summary-totals">${summaryLine('Taxable amount',c.taxable)}${c.cgst?summaryLine('CGST',c.cgst):''}${c.sgst?summaryLine('SGST',c.sgst):''}${c.igst?summaryLine('IGST',c.igst):''}${c.cess?summaryLine('Cess',c.cess):''}${summaryLine('Round off',c.round)}<div class="summary-line total"><span>Grand total</span><b>${inr(c.grand)}</b></div>${summaryLine('Balance due',c.balance)}</div></section></div><div class="preview-sticky"><div class="preview-bar"><span>Live A4 preview</span><div class="preview-controls"><span>${data.plan==='Free'?'Free plan · iluvinvoice.net watermark':'Pro · Clean PDF'}</span><select id="previewTemplate">${['minimal','modern','corporate','elegant','classic'].map(x=>`<option value="${x}" ${state.template===x?'selected':''} ${data.plan==='Free'&&['corporate','elegant','classic'].includes(x)?'disabled':''}>${x[0].toUpperCase()+x.slice(1)}${data.plan==='Free'&&['corporate','elegant','classic'].includes(x)?' · Pro':''}</option>`).join('')}</select></div></div><div class="a4-wrap"><div class="a4-paper" id="paper"></div></div></div></div></div>`}
function summaryLine(label,value){return `<div class="summary-line"><span>${label}</span><b>${inr(value)}</b></div>`}
function invoicePaymentState(invoice){let total=toPaise(invoice.amount||'0'),paid=invoice.status==='Paid'?total:toPaise(invoice.paid||'0');return derivePaymentState(total,paid,invoice.due)}
function recordPaymentModal(invoiceId=''){let open=data.invoices.filter(i=>!['Draft','Paid','Void'].includes(i.status)&&invoicePaymentState(i).balance>0n);if(!open.length){toast('There are no open invoices to record a payment against.','error');return}let selected=open.find(i=>i.id===invoiceId)||open[0],balance=invoicePaymentState(selected).balance;showModal('Record a payment','Log a receipt already received offline.',`<form id="receiptForm"><div class="field-grid"><div class="field full"><label>Invoice</label><select name="invoiceId">${open.map(i=>`<option value="${esc(i.id)}" ${i.id===selected.id?'selected':''}>${esc(i.id)} · ${esc(i.customer)} · ${inr(invoicePaymentState(i).balance)} due</option>`).join('')}</select></div><div class="field"><label>Amount received (₹)</label><input name="amount" type="number" min="0.01" step="0.01" max="${esc(paiseToDecimal(balance))}" value="${esc(paiseToDecimal(balance))}" required></div><div class="field"><label>Date received</label><input name="date" type="date" value="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>Method</label><select name="method"><option>Bank transfer</option><option>UPI</option><option>Cash</option><option>Card</option><option>Other</option></select></div><div class="field"><label>Reference (optional)</label><input name="reference" placeholder="UTR / transaction note"></div></div><div class="helper">This records a payment you have already received. iluvinvoice.net does not move money in this preview.</div></form>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="submit-payment">Save receipt</button>`)}
function previewHTMLLegacy(inv,template=state.template,includeWatermark=data.plan==='Free'){let paidValue=inv.paid||(inv.status==='Paid'?inv.amount:'0'),c=calculate(inv.items||[],inv.place||data.business.state,paidValue),b=data.business,party=inv.customer||'Customer name',invNum=inv.id||'INV/26-27/001';let rows=(inv.items||[]).map(it=>{let l=lineMath(it);return `<tr><td><strong>${esc(it.name||'Item')}</strong><div class="pv-item-desc">${esc(it.description||'')}</div></td><td>${esc(it.hsn||'—')}</td><td>${esc(it.qty||'0')} ${esc(it.unit||'')}</td><td>${inr(toPaise(it.rate||'0'))}</td><td>${inr(l.taxable)}</td><td>${Number(it.gst)||0}%</td><td>${inr(l.tax+l.cess)}</td><td>${inr(l.total)}</td></tr>`}).join('');let bank=(b.bank||b.account||b.upi)?`<div><h5>Payment details</h5><div>${b.bank?`<strong>${esc(b.bank)}</strong><br>`:''}${b.account?`A/c ${esc(b.account)} · IFSC ${esc(b.ifsc)}<br>`:''}${b.upi?`UPI: ${esc(b.upi)}`:''}</div></div>`:`<div></div>`;return `<div class="invoice-preview template-${esc(template)}">${includeWatermark?`<div class="preview-watermark">Created with ${BRAND}</div>`:''}<div class="pv-head"><div class="pv-brand"><div class="pv-logo">${b.logoData?`<img src="${esc(b.logoData)}" alt="Business logo" style="max-width:100%;max-height:100%;object-fit:contain">`:esc((b.tradeName||'S').slice(0,1))}</div><div><div class="pv-seller">${esc(b.tradeName||b.legalName||'Your business name')}</div><div class="pv-seller-sub">${esc(b.address||'')}<br>${esc(b.state||'')} ${esc(b.stateCode||'')} · GSTIN ${esc(b.gstin||'')}<br>${esc(b.phone||'')} · ${esc(b.email||'')}${b.pan?` · PAN ${esc(b.pan)}`:''}</div></div></div><div class="pv-invoice-heading"><strong>${esc(inv.type||'Tax Invoice').toUpperCase()}</strong><small>${esc(invNum)}</small><small>Original for recipient</small></div></div><div class="pv-doc-info"><div><div class="pv-block-title">Bill to</div><strong>${esc(party)}</strong>${inv.gstin?`<div>GSTIN: ${esc(inv.gstin)}</div>`:'<div>Unregistered customer</div>'}<div>${esc(inv.address||'')}</div><div>${esc(inv.state||'')} ${esc(inv.stateCode||'')}</div>${inv.shipping?`<div class="pv-block-title" style="margin-top:5px">Ship to</div><div>${esc(inv.shipping)}</div>`:''}</div><div class="pv-doc-meta"><div class="pv-meta-line">Invoice date<br><b>${dateFmt(inv.date)}</b></div><div class="pv-meta-line">Due date<br><b>${dateFmt(inv.due)}</b></div><div class="pv-meta-line">Place of supply<br><b>${esc(inv.place||'')}</b></div><div class="pv-meta-line">Reverse charge<br><b>${inv.reverse?'Yes':'No'}</b></div>${inv.reference?`<div class="pv-meta-line">Reference / PO<br><b>${esc(inv.reference)}</b></div>`:''}${inv.customLabel&&inv.customValue?`<div class="pv-meta-line">${esc(inv.customLabel)}<br><b>${esc(inv.customValue)}</b></div>`:''}</div></div><table class="pv-items"><thead><tr><th>Description</th><th>HSN/SAC</th><th>Qty</th><th>Rate</th><th>Taxable</th><th>GST</th><th>Tax</th><th>Amount</th></tr></thead><tbody>${rows||'<tr><td colspan="8">Add items to preview your invoice.</td></tr>'}</tbody></table><div class="pv-lower"><div><h5>Tax summary</h5><div class="pv-tax-lines">${c.cgst?`<div class="pv-tax-line"><span>CGST</span><b>${inr(c.cgst)}</b></div>`:''}${c.sgst?`<div class="pv-tax-line"><span>SGST</span><b>${inr(c.sgst)}</b></div>`:''}${c.igst?`<div class="pv-tax-line"><span>IGST</span><b>${inr(c.igst)}</b></div>`:''}${c.cess?`<div class="pv-tax-line"><span>Cess</span><b>${inr(c.cess)}</b></div>`:''}${c.discount?`<div class="pv-tax-line"><span>Discount</span><b>− ${inr(c.discount)}</b></div>`:''}<div class="pv-tax-line"><span>Round off</span><b>${inr(c.round)}</b></div></div><div class="pv-words">Amount in words<br><strong>${esc(rupeesWords(c.grand))}</strong></div></div><div>${bank}<div class="pv-grand"><span>Grand total</span><span>${inr(c.grand)}</span></div>${c.paid>0n?`<div class="pv-tax-line" style="margin-top:4px"><span>Paid / Balance</span><b>${inr(c.paid)} / ${inr(c.balance)}</b></div>`:''}</div></div><div class="pv-bottom"><div><strong>Terms & conditions</strong><br>${esc(b.terms||'Payment due as per agreed terms.')}<br>${inv.notes?`<br><strong>Note:</strong> ${esc(inv.notes)}`:''}</div><div class="pv-sign">${b.signatureData?`<img src="${esc(b.signatureData)}" alt="Signature" style="max-width:100%;max-height:22px;object-fit:contain"><br>`:''}<strong>${esc(b.signatory||'Authorised signatory')}</strong><br>Authorised signatory</div></div><div class="pv-footer">This is a computer generated document. Please verify all details before making payment.</div></div>`}
function mountEditorTemplateGallery(){if(!state.editor)return;const typeSelect=document.querySelector('[data-draft="type"]');if(typeSelect&&!typeSelect.querySelector('option[value="Invoice"]')){const option=document.createElement('option');option.value='Invoice';option.textContent='Invoice';typeSelect.querySelector('option')?.after(option);typeSelect.value=state.draft.type}const customerHeading=[...document.querySelectorAll('.form-card-heading h3')].find(x=>x.textContent.trim()==='Customer details'),customerGrid=customerHeading?.closest('.form-card')?.querySelector('.field-grid');if(customerGrid&&!customerGrid.querySelector('[data-customer-extra]')){customerGrid.insertAdjacentHTML('beforeend',`<div class="field" data-customer-extra><label>Customer PAN</label><input data-draft="customerPan" value="${esc(state.draft.customerPan||'')}" placeholder="Optional PAN"></div><div class="field" data-customer-extra><label>Customer email</label><input type="email" data-draft="customerEmail" value="${esc(state.draft.customerEmail||'')}" placeholder="name@example.com"></div><div class="field" data-customer-extra><label>Customer phone</label><input data-draft="customerPhone" value="${esc(state.draft.customerPhone||'')}" placeholder="Phone number"></div><div class="field" data-customer-extra><label>Country</label><input data-draft="customerCountry" value="${esc(state.draft.customerCountry||'')}" placeholder="e.g. India"></div><div class="field" data-customer-extra><label>PIN / postal code</label><input data-draft="customerPostal" value="${esc(state.draft.customerPostal||'')}" placeholder="e.g. 210431"></div>`)}if(document.querySelector('.editor-template-gallery'))return;const wrap=document.querySelector('.a4-wrap');if(!wrap)return;const styles=[['minimal','Minimal'],['modern','Modern Teal'],['corporate','Corporate'],['elegant','Elegant'],['classic','Classic GST'],['ocean','Ocean'],['burgundy','Burgundy'],['graphite','Graphite']];wrap.insertAdjacentHTML('afterend',`<section class="editor-template-gallery"><div><strong>Choose invoice style</strong><small>Preview and switch instantly</small></div><div class="editor-template-scroll">${styles.map(([key,label])=>`<button class="editor-template-choice ${state.template===key?'active':''}" data-action="select-template" data-template="${key}"><i class="template-swatch swatch-${key}"></i><span>${label}</span>${state.template===key?'<b>✓</b>':''}</button>`).join('')}</div></section>`)}
function updatePreview(){if(!state.editor)return;let fy=document.querySelector('[data-fy]');if(fy)fy.innerHTML=`<option>${financialYear(state.draft.date).replace('-','–')}</option>`;let p=document.getElementById('paper');if(p)p.innerHTML=previewHTML(state.draft,state.template,data.plan==='Free');mountEditorTemplateGallery();let hint=document.querySelector('.summary-card .helper');if(hint)hint.textContent=`${state.draft.place===data.business.state?'Intra-state supply · CGST + SGST':'Inter-state supply · IGST'}${state.draft.reverse?' · Reverse charge':''}`;let s=document.querySelector('.summary-totals');if(s){let c=calculate(state.draft.items,state.draft.place);s.innerHTML=`${summaryLine('Taxable amount',c.taxable)}${c.cgst?summaryLine('CGST',c.cgst):''}${c.sgst?summaryLine('SGST',c.sgst):''}${c.igst?summaryLine('IGST',c.igst):''}${c.cess?summaryLine('Cess',c.cess):''}${summaryLine('Round off',c.round)}<div class="summary-line total"><span>Grand total</span><b>${inr(c.grand)}</b></div>${summaryLine('Balance due',c.balance)}`};document.querySelectorAll('.item-edit-table tbody tr').forEach((tr,i)=>{let cell=tr.querySelector('td:nth-last-child(2)');if(cell&&state.draft.items[i])cell.textContent=inr(lineMath(state.draft.items[i]).total)})}
function toast(message,type='success'){let el=document.getElementById('toastArea');if(!el)return;let t=document.createElement('div');t.className=`toast ${type}`;t.textContent=message;el.append(t);setTimeout(()=>t.remove(),3100)}
function showModal(title,sub,content,actions){state.modal={title,sub,content,actions};let old=document.querySelector('.modal-backdrop');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modalBackdrop"><section class="modal"><header class="modal-header"><div><h2>${title}</h2><p>${sub}</p></div><button class="modal-close" data-action="close-modal">${ico('close',15)}</button></header><div class="modal-content">${content}</div><footer class="modal-actions">${actions}</footer></section></div>`)}
function closeModal(){document.querySelector('.modal-backdrop')?.remove();state.modal=null}
function previewHTML(inv,template=state.template,includeWatermark=data.plan==='Free'){
  const paidValue=inv.paid||(inv.status==='Paid'?inv.amount:'0'),c=calculate(inv.items||[],inv.place||data.business.state,paidValue),b=data.business,party=inv.customer||'',invNum=inv.id||'INV/26-27/001',customer=data.customers.find(x=>(x.business||x.name)===party||x.name===party)||{};
  const intra=!c.igst, taxA=intra?'CGST':'IGST', taxB=intra?'SGST':'Cess';
  const rows=(inv.items||[]).map(it=>{const l=lineMath(it),first=intra?l.tax/2n:l.tax,second=intra?l.tax-first:l.cess;return `<tr><td><strong>${esc(it.name||'Item')}</strong>${it.description?`<div class="pv-item-desc">${esc(it.description)}</div>`:''}</td><td>${Number(it.gst)||0}%</td><td>${esc(it.qty||'0')} ${esc(it.unit||'')}</td><td>${inr(toPaise(it.rate||'0'))}</td><td>${inr(l.taxable)}</td><td>${inr(first)}</td><td>${inr(second)}</td><td><strong>${inr(l.total)}</strong></td></tr>`}).join('');
  const qrAmount=Number(paiseToDecimal(c.balance>0n?c.balance:c.grand))||0, qr=b.upi?`/api/upi-qr?upi=${encodeURIComponent(b.upi)}&name=${encodeURIComponent(b.tradeName||b.legalName||'Business')}&invoice=${encodeURIComponent(invNum)}&amount=${encodeURIComponent(qrAmount)}`:'';
  const sellerName=b.tradeName||b.legalName||'',buyerName=customer.business||party,detailList=items=>{const rows=items.filter(([,value])=>String(value??'').trim());return rows.length?`<dl>${rows.map(([label,value])=>`<dt>${esc(label)}</dt><dd>${esc(value)}</dd>`).join('')}</dl>`:''};
  const sellerCard=(sellerName||b.address||b.gstin||b.pan||b.email||b.phone)?`<section><h3>Billed By</h3>${sellerName?`<strong>${esc(sellerName)}</strong>`:''}${b.address?`<p>${esc(b.address)}</p>`:''}${detailList([['GSTIN',b.gstin],['PAN',b.pan],['Email',b.email],['Phone',b.phone]])}</section>`:'';
  const buyerAddress=inv.address||customer.address||'',buyerCountry=inv.customerCountry||customer.country||'',buyerPostal=inv.customerPostal||customer.postal||'',buyerLocation=[inv.state||customer.state,buyerCountry].filter(Boolean).join(', ')+(buyerPostal?` - ${buyerPostal}`:''),buyerPan=inv.customerPan||customer.pan||'',buyerEmail=inv.customerEmail||customer.email||'',buyerPhone=inv.customerPhone||customer.phone||'',buyerCard=(buyerName||buyerAddress||buyerLocation||inv.gstin||customer.gstin||buyerPan||buyerEmail||buyerPhone)?`<section><h3>Billed To</h3>${buyerName?`<strong>${esc(buyerName)}</strong>`:''}${buyerAddress?`<p>${esc(buyerAddress)}</p>`:''}${buyerLocation?`<p class="ref-location">${esc(buyerLocation)}</p>`:''}${detailList([['GSTIN',inv.gstin||customer.gstin],['PAN',buyerPan],['Email',buyerEmail],['Phone',buyerPhone]])}</section>`:'';
  const bankRows=detailList([['Account Name',sellerName],['Account Number',b.account],['IFSC',b.ifsc],['Bank',b.bank]]),paymentBlocks=[(b.bank||b.account||b.ifsc)?`<section class="ref-bank"><h3>Bank Details</h3>${bankRows}</section>`:'',qr?`<section class="ref-qr"><h3>Scan to pay via UPI</h3><img src="${qr}" alt="UPI payment QR"><strong>${esc(b.upi)}</strong></section>`:'',(b.signatureData||b.signatory)?`<section class="ref-sign">${b.signatureData?`<img src="${esc(b.signatureData)}" alt="Signature">`:''}${b.signatory?`<div>${esc(b.signatory)}</div>`:''}<strong>Authorized Signatory</strong></section>`:''].filter(Boolean).join('');
  return `<div class="invoice-preview reference-invoice template-${esc(template)}">${includeWatermark?`<div class="preview-watermark">Created with ${BRAND}</div>`:''}${sellerName?`<div class="ref-brand-strip">${esc(sellerName)}</div>`:''}
  <div class="ref-title-row"><div><h1>${esc(inv.type||'Invoice')}</h1>${invNum?`<div><b>Invoice No:</b> ${esc(invNum)}</div>`:''}${inv.date?`<div><b>Date:</b> ${dateFmt(inv.date)}</div>`:''}</div>${b.logoData?`<div class="ref-logo"><img src="${esc(b.logoData)}" alt="Business logo"></div>`:''}</div>
  ${(sellerCard||buyerCard)?`<div class="ref-party-grid ${sellerCard&&buyerCard?'':'single'}">${sellerCard}${buyerCard}</div>`:''}
  <table class="pv-items ref-items"><thead><tr><th>Item</th><th>GST Rate</th><th>Quantity</th><th>Rate</th><th>Amount</th><th>${taxA}</th><th>${taxB}</th><th>Total</th></tr></thead><tbody>${rows||'<tr><td colspan="8">Add items to preview your invoice.</td></tr>'}</tbody></table>
  <div class="ref-summary"><div class="ref-words"><span>Invoice Amount In Words</span><strong>${esc(rupeesWords(c.grand))}</strong></div><div class="ref-totals"><div><span>Amount</span><b>${inr(c.taxable)}</b></div>${intra?`<div><span>CGST</span><b>${inr(c.cgst)}</b></div><div><span>SGST</span><b>${inr(c.sgst)}</b></div>`:`<div><span>IGST</span><b>${inr(c.igst)}</b></div>`}${c.cess?`<div><span>Cess</span><b>${inr(c.cess)}</b></div>`:''}<div class="total"><span>Total (INR)</span><b>${inr(c.grand)}</b></div>${c.paid>0n?`<div><span>Balance Due</span><b>${inr(c.balance)}</b></div>`:''}</div></div>
  ${paymentBlocks?`<div class="ref-payment-row" style="--payment-cols:${paymentBlocks.match(/<section/g)?.length||1}">${paymentBlocks}</div>`:''}
  ${(b.terms||inv.notes)?`<div class="ref-terms"><h3>Terms and Conditions</h3><p>${b.terms?esc(b.terms):''}${inv.notes?` ${esc(inv.notes)}`:''}</p></div>`:''}<div class="pv-footer"><span class="invoice-powered-copy">Powered by</span><span class="invoice-powered-brand"><span class="invoice-powered-mark" aria-hidden="true"><svg viewBox="0 0 24 24" role="img"><path d="M12 21S3 15.6 3 8.8C3 5 7.4 3.2 12 7.4 16.6 3.2 21 5 21 8.8 21 15.6 12 21 12 21Z"/></svg></span><span>iluvinvoice.net</span></span></div></div>`;
}
function addCustomerModal(customer){let c=customer||{};showModal(customer?'Edit customer':'Add a customer','Keep useful details close at hand.',`<form id="customerForm"><input type="hidden" name="id" value="${esc(c.id||'')}"><div class="field-grid"><div class="field"><label>Contact name</label><input name="name" required value="${esc(c.name||'')}" placeholder="e.g. Aarav Mehta"></div><div class="field"><label>Business name</label><input name="business" value="${esc(c.business||'')}" placeholder="e.g. Mehta & Co."></div><div class="field"><label>GSTIN / UIN</label><input name="gstin" value="${esc(c.gstin||'')}" maxlength="15" placeholder="Optional"></div><div class="field"><label>PAN (optional)</label><input name="pan" value="${esc(c.pan||'')}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(c.phone||'')}"></div><div class="field"><label>Email</label><input name="email" type="email" value="${esc(c.email||'')}"></div><div class="field"><label>State</label><select name="state">${stateOptions(c.state||'Uttar Pradesh')}</select></div><div class="field"><label>State code</label><input name="stateCode" value="${esc(c.stateCode||'09')}"></div><div class="field full"><label>Billing address</label><input name="address" value="${esc(c.address||'')}"></div></div></form>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="submit-customer">Save customer</button>`)}
function addProductModal(product){let p=product||{};showModal(product?'Edit product':'Add a product or service','Saved items make invoicing quicker.',`<form id="productForm"><input type="hidden" name="id" value="${esc(p.id||'')}"><div class="field-grid"><div class="field full"><label>Name</label><input name="name" required value="${esc(p.name||'')}" placeholder="Product or service name"></div><div class="field full"><label>Description</label><input name="description" value="${esc(p.description||'')}"></div><div class="field"><label>HSN / SAC</label><input name="hsn" value="${esc(p.hsn||'')}"></div><div class="field"><label>Unit</label><input name="unit" value="${esc(p.unit||'Unit')}"></div><div class="field"><label>Default price (₹)</label><input type="number" min="0" step="0.01" name="price" required value="${esc(p.price||'')}"></div><div class="field"><label>GST rate (%)</label><select name="gst">${[...new Set([...data.taxRates,Number(p.gst)||0])].sort((a,b)=>a-b).map(x=>`<option ${Number(p.gst)===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Cess (%)</label><select name="cess">${[...new Set([...data.cessRates,Number(p.cess)||0])].sort((a,b)=>a-b).map(x=>`<option ${Number(p.cess)===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="helper">Tax classifications and rates are configurable defaults, not legal or classification advice.</div></form>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="submit-product">Save item</button>`)}
function upgradeModal(){showModal('Choose the room you need','Simple plans for growing businesses.',`<div style="display:grid;gap:10px"><div class="settings-card" style="padding:14px;box-shadow:none"><div style="display:flex;justify-content:space-between"><strong>Free</strong><b>₹0</b></div><p style="margin:6px 0 0">10 invoices / month · 2 templates · iluvinvoice.net watermark</p></div><div class="settings-card" style="padding:14px;border-color:#bad6c3;box-shadow:none"><div style="display:flex;justify-content:space-between"><strong>Pro Monthly</strong><b>₹399 <small>/ month</small></b></div><p style="margin:6px 0 0">Unlimited invoices · all templates · clean PDFs · logo & signature</p></div><div class="settings-card" style="padding:14px;box-shadow:none"><div style="display:flex;justify-content:space-between"><strong>Pro Yearly</strong><b>₹3,990 <small>/ year</small></b></div><p style="margin:6px 0 0">Save 2 months · the same complete Pro toolkit</p></div><div class="modal-message">Payments are not connected in this preview. No charge will be made. A production release should use a verified payment provider with server-side subscription entitlements.</div></div>`,`<button class="button button-secondary" data-action="close-modal">Maybe later</button><button class="button button-primary" data-action="start-pro">Preview Pro access</button>`)}
function accountModal(){showModal('Account & security','Manage your iluvinvoice.net account.',`<div class="field-grid"><div class="field full"><label>Account email</label><input value="${esc(data.businessEmail||'your.com')}" disabled><div class="helper">Email verification is not enabled in this local preview.</div></div><div class="field full"><label>Password</label><button class="button button-secondary" style="width:100%" data-action="toast-security">Change password</button></div><div class="field full"><label>Sign in protection</label><div class="modal-message">Authentication, verification, recovery and role enforcement require the production backend.</div></div></div>`,`<button class="button button-secondary" data-action="close-modal">Close</button>`)}
function saveInvoice(){let d=state.draft;if(!d.customer.trim()){toast('Add a customer name before saving.','error');return}if(!d.items.some(x=>x.name.trim())){toast('Add at least one item before saving.','error');return}if(d.gstin&&!/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/.test(d.gstin.toUpperCase())){toast('That GSTIN format looks incomplete. Please review it.','error');return}let found=data.customers.find(c=>(c.business||c.name)===d.customer);if(found){d.gstin=d.gstin||found.gstin;d.address=d.address||found.address;d.state=d.state||found.state;d.stateCode=d.stateCode||found.stateCode}let calc=calculate(d.items,d.place);if(toPaise(d.paid||'0')>calc.grand){toast('Amount paid cannot exceed the invoice total.','error');return}d.amount=paiseToDecimal(calc.grand);d.status=calc.paid>=calc.grand?'Paid':calc.paid>0?'Partially Paid':new Date(d.due+'T23:59:59')<new Date()?'Overdue':'Unpaid';let originalId=d.saved?d.originalId:null;let ix=originalId?data.invoices.findIndex(i=>i.id===originalId):-1;let duplicate=data.invoices.find(i=>i.id===d.id&&financialYear(i.date)===financialYear(d.date)&&i.id!==originalId);if(duplicate){toast('This invoice number is already used in this financial year. Choose a unique number.','error');return}if(d.saved&&ix>=0){let saved={...d};delete saved.saved;delete saved.originalId;data.invoices[ix]=JSON.parse(JSON.stringify(saved))}else{if(data.plan==='Free'&&data.invoiceCount>=10){toast('Free plan limit reached. Explore Pro to continue.','error');return}let saved={...d};delete saved.saved;delete saved.originalId;data.invoices.unshift(JSON.parse(JSON.stringify(saved)));data.invoiceCount++}state.editor=false;state.draft=null;state.page='Invoices';persist();render();toast('Invoice saved. Your changes are in this browser.');}
function changePage(p){if(p==='Water Plant'){location.href='/water-plant';return}state.editor=false;state.page=p;state.search='';persist();render()}
function duplicateInvoice(id){let x=data.invoices.find(i=>i.id===id);if(!x)return;let d=JSON.parse(JSON.stringify(x));d.saved=false;delete d.originalId;d.id=nextInvoiceNumber();d.date=new Date().toISOString().slice(0,10);d.due=new Date(Date.now()+14*86400000).toISOString().slice(0,10);d.status='Draft';d.paid='0';state.draft=d;state.editor=true;render()}
function printInvoice(inv){let html=previewHTML(inv,state.template,data.plan==='Free');let root=document.createElement('div');root.className='print-root';root.innerHTML=`<div class="a4-paper">${html}</div>`;document.body.append(root);let remove=()=>root.remove();window.addEventListener('afterprint',remove,{once:true});setTimeout(()=>{window.print();setTimeout(remove,1200)},100)}
function invoiceSummaryText(inv){let pay=invoicePaymentState(inv);return `${BRAND} invoice ${inv.id}\nCustomer: ${inv.customer}\nTotal: ${inr(toPaise(inv.amount))}\nPaid: ${inr(pay.paid)}\nBalance due: ${inr(pay.balance)}\nDue date: ${dateFmt(inv.due)}`}
async function copyInvoiceSummary(id){let inv=data.invoices.find(i=>i.id===id);if(!inv)return;try{await navigator.clipboard.writeText(invoiceSummaryText(inv));toast('Invoice summary copied to clipboard.')}catch{toast('Clipboard access is unavailable in this browser.','error')}}
function sendReminder(id){let inv=data.invoices.find(i=>i.id===id);if(!inv)return;let customer=data.customers.find(c=>(c.business||c.name)===inv.customer||c.name===inv.customer),email=customer?.email;if(!email){toast('Add an email address to this customer first.','error');return}let balance=invoicePaymentState(inv).balance;if(balance<=0n){toast('This invoice has no outstanding balance.','error');return}let subject=encodeURIComponent(`Payment reminder · ${inv.id}`),body=encodeURIComponent(`Hi ${customer.name},\n\nA friendly reminder that invoice ${inv.id} for ${inr(balance)} is outstanding${inv.due?` and was due on ${dateFmt(inv.due)}`:''}.\n\nPlease let us know if you have any questions.\n\nThank you,\n${data.business.tradeName||data.business.legalName}`);window.open(`mailto:${encodeURIComponent(email)}?subject=${subject}&body=${body}`,'_blank','noopener');toast('Email app opened with a draft. Review and send it there.')}
function csvExport(){let rows=[['Invoice','Customer','GSTIN','Date','Due date','Status','Amount'],...data.invoices.map(i=>[i.id,i.customer,i.gstin||'',i.date,i.due,i.status,paiseToDecimal(toPaise(i.amount))])];let blob=new Blob([rows.map(r=>r.map(x=>{let s=String(x);if(/^\s*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(',')).join('\n')],{type:'text/csv'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='invoiceflow-invoices.csv';a.click();URL.revokeObjectURL(a.href)}
function handleAction(btn){let a=btn.dataset.action,id=btn.dataset.id;if(a==='workspace'){state.editor=false;state.page='Settings';render();setTimeout(()=>document.querySelector('#businessForm input[name="legalName"]')?.focus(),50)}else if(a==='new'){if(data.plan==='Free'&&data.invoiceCount>=10){upgradeModal();return}if(state.draft){showModal('You have an invoice draft','Pick up where you left off or start fresh.',`<div class="modal-message">${esc(state.draft.id||'New invoice')} is saved in this browser. You can resume it or replace it with a new invoice.</div>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-secondary" data-action="resume-draft">Resume draft</button><button class="button button-primary" data-action="start-new-draft">Start fresh</button>`);return}newDraft()}else if(a==='close-editor'){state.editor=false;state.page='Overview';persist();render()}else if(a==='resume-draft'){closeModal();state.editor=true;state.page='Invoices';render()}else if(a==='start-new-draft'){closeModal();state.draft=null;persist();newDraft()}else if(a==='discard-draft'){state.draft=null;persist();render();toast('Local draft discarded.')}else if(a==='save-invoice')saveInvoice();else if(a==='add-item'){state.draft.items.push({name:'',description:'',hsn:'',qty:'1',unit:'Unit',rate:'0',discount:'0',gst:18,cess:0});render()}else if(a==='remove-item'){if(state.draft.items.length===1){toast('An invoice needs at least one item.','error');return}state.draft.items.splice(Number(btn.dataset.i),1);render()}else if(a==='reverse-toggle'){state.draft.reverse=!state.draft.reverse;btn.classList.toggle('on',state.draft.reverse);persist();updatePreview()}else if(a==='add-customer')addCustomerModal();else if(a==='edit-customer')addCustomerModal(data.customers.find(x=>x.id===id));else if(a==='add-product')addProductModal();else if(a==='edit-product')addProductModal(data.products.find(x=>x.id===id));else if(a==='close-modal')closeModal();else if(a==='submit-customer')document.getElementById('customerForm')?.requestSubmit();else if(a==='submit-product')document.getElementById('productForm')?.requestSubmit();else if(a==='upgrade')upgradeModal();else if(a==='start-pro'){data.plan='Pro';persist();closeModal();render();toast('Pro preview enabled on this device. No payment was taken.')}else if(a==='theme'){data.theme=data.theme==='dark'?'light':'dark';persist();render()}else if(a==='account')accountModal();else if(a==='notifications')showModal('You’re all caught up','No new notifications.',`<div class="modal-message">Payment reminders, invoice updates and account activity will appear here.</div>`,`<button class="button button-primary" data-action="close-modal">Nice</button>`);else if(a==='select-template'){if(btn.dataset.locked){upgradeModal();return}data.template=btn.dataset.template;state.template=data.template;persist();render();toast('Template updated.')}else if(a==='view-invoice'){let invoice=data.invoices.find(i=>i.id===id);if(invoice){state.draft={...JSON.parse(JSON.stringify(invoice)),saved:true,originalId:invoice.id,paid:invoice.paid||(invoice.status==='Paid'?invoice.amount:'0')};state.editor=true;state.page='Invoices';render()}}else if(a==='invoice-menu'){showModal('Invoice actions',id,`<div class="modal-message">Choose an action for ${esc(id)}. Reminders open your own email app; no message is sent by iluvinvoice.net.</div><div class="invoice-action-grid"><button class="button button-secondary" data-action="record-payment" data-id="${esc(id)}">${ico('payment',14)} Record payment</button><button class="button button-secondary" data-action="send-reminder" data-id="${esc(id)}">${ico('mail',14)} Email reminder</button><button class="button button-secondary" data-action="copy-invoice" data-id="${esc(id)}">${ico('file',14)} Copy summary</button><button class="button button-secondary" data-action="duplicate" data-id="${esc(id)}">${ico('plus',14)} Duplicate</button></div>`,`<button class="button button-secondary" data-action="close-modal">Close</button><button class="button button-primary" data-action="print-saved" data-id="${esc(id)}">Print / PDF</button>`)}else if(a==='duplicate'){closeModal();duplicateInvoice(id)}else if(a==='print-saved'){let inv=data.invoices.find(i=>i.id===id);closeModal();if(inv)printInvoice(inv)}else if(a==='preview-download'){printInvoice(state.draft)}else if(a==='record-payment')recordPaymentModal(id);else if(a==='send-reminder')sendReminder(id);else if(a==='copy-invoice')copyInvoiceSummary(id);else if(a==='submit-payment')document.getElementById('receiptForm')?.requestSubmit();else if(a==='export')csvExport();else if(a==='toast-security')toast('Password reset requires a verified production account.','error');}
document.addEventListener('click',e=>{let page=e.target.closest('[data-page]');if(page){changePage(page.dataset.page);return}let filter=e.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;render();return}let btn=e.target.closest('[data-action]');if(btn){handleAction(btn);return}if(e.target.id==='modalBackdrop')closeModal()});
document.addEventListener('input',e=>{if(e.target.id==='globalSearch'||e.target.id==='pageSearch'){state.search=e.target.value;let pos=e.target.selectionStart;let id=e.target.id;render();let next=document.getElementById(id);if(next){next.focus();next.setSelectionRange(pos,pos)}return}if(state.editor&&e.target.dataset.business){data.business[e.target.dataset.business]=e.target.value;persist();updatePreview();return}if(state.editor&&e.target.dataset.draft){let k=e.target.dataset.draft;state.draft[k]=e.target.value;if(k==='customer'){let c=data.customers.find(x=>(x.business||x.name).toLowerCase()===e.target.value.toLowerCase());if(c){state.draft.gstin=c.gstin||'';state.draft.address=c.address||'';state.draft.state=c.state||'';state.draft.stateCode=c.stateCode||'';state.draft.place=c.state||data.business.state;state.draft.supply=c.gstin?'B2B':'B2C';document.querySelector('[data-draft="supply"]').value=state.draft.supply;document.querySelector('[data-draft="gstin"]').value=state.draft.gstin;document.querySelector('[data-draft="address"]').value=state.draft.address;document.querySelector('[data-draft="state"]').value=state.draft.state;document.querySelector('[data-draft="stateCode"]').value=state.draft.stateCode;document.querySelector('[data-draft="place"]').value=state.draft.place}}persist();updatePreview();return}if(state.editor&&e.target.dataset.item){let i=Number(e.target.dataset.i),k=e.target.dataset.item;if(state.draft.items[i])state.draft.items[i][k]=e.target.value;if(k==='name'){let p=data.products.find(x=>x.name.toLowerCase()===e.target.value.toLowerCase());if(p){Object.assign(state.draft.items[i],{description:p.description,hsn:p.hsn,rate:p.price,unit:p.unit,gst:p.gst,cess:p.cess});let row=e.target.closest('tr');for(let x of row.querySelectorAll('[data-item]'))x.value=state.draft.items[i][x.dataset.item]??''}}persist();updatePreview()}});
document.addEventListener('change',e=>{if(e.target.name==='state'){const form=e.target.closest('form'),codes={'Jammu and Kashmir':'01','Himachal Pradesh':'02','Punjab':'03','Chandigarh':'04','Uttarakhand':'05','Haryana':'06','Delhi':'07','Rajasthan':'08','Uttar Pradesh':'09','Bihar':'10','Sikkim':'11','Arunachal Pradesh':'12','Nagaland':'13','Manipur':'14','Mizoram':'15','Tripura':'16','Meghalaya':'17','Assam':'18','West Bengal':'19','Jharkhand':'20','Odisha':'21','Chhattisgarh':'22','Madhya Pradesh':'23','Gujarat':'24','Dadra and Nagar Haveli and Daman and Diu':'26','Maharashtra':'27','Karnataka':'29','Goa':'30','Lakshadweep':'31','Kerala':'32','Tamil Nadu':'33','Puducherry':'34','Andaman and Nicobar Islands':'35','Telangana':'36','Andhra Pradesh':'37','Ladakh':'38'};const code=form?.querySelector('[name="stateCode"]');if(code&&codes[e.target.value])code.value=codes[e.target.value]}if(e.target.form?.id==='receiptForm'&&e.target.name==='invoiceId'){let invoice=data.invoices.find(i=>i.id===e.target.value),amountField=document.querySelector('#receiptForm [name="amount"]');if(invoice&&amountField){let balance=invoicePaymentState(invoice).balance;amountField.max=paiseToDecimal(balance);amountField.value=paiseToDecimal(balance)}}if(e.target.dataset.upload){const file=e.target.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>512000){toast('Choose a PNG, JPG or WebP image under 500 KB.','error');e.target.value='';return}const reader=new FileReader();reader.onload=()=>{data.business[`${e.target.dataset.upload}Data`]=reader.result;persist();render();toast('Brand asset saved on this device.')} ;reader.readAsDataURL(file);return}if(e.target.id==='previewTemplate'){state.template=e.target.value;data.template=state.template;persist();updatePreview()}if(e.target.id==='quickProduct'&&e.target.value){let p=data.products.find(x=>x.id===e.target.value);if(p){state.draft.items.push({name:p.name,description:p.description,hsn:p.hsn,qty:'1',unit:p.unit,rate:p.price,discount:'0',gst:p.gst,cess:p.cess});render()}}if(state.editor&&e.target.dataset.draft){let k=e.target.dataset.draft;state.draft[k]=e.target.value;if(k==='state'){let m={'Jammu and Kashmir':'01','Himachal Pradesh':'02','Punjab':'03','Chandigarh':'04','Uttarakhand':'05','Haryana':'06','Delhi':'07','Rajasthan':'08','Uttar Pradesh':'09','Bihar':'10','Sikkim':'11','Arunachal Pradesh':'12','Nagaland':'13','Manipur':'14','Mizoram':'15','Tripura':'16','Meghalaya':'17','Assam':'18','West Bengal':'19','Jharkhand':'20','Odisha':'21','Chhattisgarh':'22','Madhya Pradesh':'23','Gujarat':'24','Dadra and Nagar Haveli and Daman and Diu':'26','Maharashtra':'27','Karnataka':'29','Goa':'30','Lakshadweep':'31','Kerala':'32','Tamil Nadu':'33','Puducherry':'34','Andaman and Nicobar Islands':'35','Telangana':'36','Andhra Pradesh':'37','Ladakh':'38'};state.draft.stateCode=m[e.target.value]||state.draft.stateCode;let code=document.querySelector('[data-draft="stateCode"]');if(code)code.value=state.draft.stateCode}persist();updatePreview()}});
document.addEventListener('submit',e=>{if(e.target.id==='customerForm'){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));let x=data.customers.find(c=>c.id===f.id);if(x)Object.assign(x,f);else{f.id=idGen('C');data.customers.unshift(f)}persist();closeModal();render();toast('Customer saved.');}if(e.target.id==='productForm'){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));f.gst=Number(f.gst);f.cess=Number(f.cess);let x=data.products.find(p=>p.id===f.id);if(x)Object.assign(x,f);else{f.id=idGen('P');data.products.unshift(f)}persist();closeModal();render();toast('Product saved.')}if(e.target.id==='receiptForm'){e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),invoice=data.invoices.find(i=>i.id===f.invoiceId);if(!invoice){toast('Select an invoice.','error');return}let amount=toPaise(f.amount),current=invoicePaymentState(invoice);if(amount<=0n){toast('Payment amount must be greater than zero.','error');return}if(amount>current.balance){toast(`Amount exceeds the remaining balance of ${inr(current.balance)}.`,'error');return}let next=derivePaymentState(current.total,current.paid+amount,invoice.due);invoice.paid=paiseToDecimal(next.paid);invoice.status=next.status;data.payments.unshift({id:`PAY-${String(Date.now()).slice(-6)}`,invoiceId:invoice.id,customer:invoice.customer,date:f.date,amount:paiseToDecimal(amount),method:f.method,reference:f.reference||''});persist();closeModal();render();toast(`Payment recorded. Invoice is now ${next.status.toLowerCase()}.`)}if(e.target.id==='taxForm'){e.preventDefault();const parseRates=v=>[...new Set(v.split(',').map(x=>Number(x.trim())).filter(x=>Number.isFinite(x)&&x>=0&&x<=100))].sort((a,b)=>a-b);data.taxRates=parseRates(new FormData(e.target).get('taxRates')||'');data.cessRates=parseRates(new FormData(e.target).get('cessRates')||'');if(!data.taxRates.includes(0))data.taxRates.unshift(0);persist();render();toast('Tax presets saved. Please review each invoice.')}if(e.target.id==='businessForm'||e.target.id==='paymentForm'){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));delete f.logoUpload;delete f.signatureUpload;if(e.target.id==='businessForm')Object.assign(data.business,f);else{Object.assign(data.business,f);if(f.invoicePrefix)data.invoicePrefix=f.invoicePrefix}persist();render();toast('Your settings are saved.')}});
function enhanceCustomerModal(){const form=document.getElementById('customerForm'),grid=form?.querySelector('.field-grid');if(!grid||grid.querySelector('[name="country"]'))return;const id=form.querySelector('[name="id"]')?.value,current=data.customers.find(c=>c.id===id)||{};grid.insertAdjacentHTML('beforeend',`<div class="field"><label>Country</label><input name="country" value="${esc(current.country||'')}" placeholder="e.g. India"></div><div class="field"><label>PIN / postal code</label><input name="postal" value="${esc(current.postal||'')}" placeholder="e.g. 210431"></div>`)}
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='add-customer'||action==='edit-customer')queueMicrotask(enhanceCustomerModal)});
document.addEventListener('input',e=>{if(!state.editor||e.target.dataset.draft!=='customer')return;const customer=data.customers.find(x=>(x.business||x.name).toLowerCase()===e.target.value.toLowerCase());if(!customer)return;const mapping={customerPan:'pan',customerEmail:'email',customerPhone:'phone',customerCountry:'country',customerPostal:'postal'};for(const [draftKey,customerKey] of Object.entries(mapping)){state.draft[draftKey]=customer[customerKey]||'';const input=document.querySelector(`[data-draft="${draftKey}"]`);if(input)input.value=state.draft[draftKey]}persist();updatePreview()});
window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('globalSearch')?.focus()}if(e.key==='Escape'){closeModal()}});
render();
